    n = len(nums)
    for i in range(n):
        for j in range(i+1, n):
            current_strength = nums[i] * nums[j]
            max_strength = max(max_strength, current_strength)
    return max_strength

def minExtraChar(s, dictionary):
    dp = [0] * (len(s) + 1)
    for i in range(1, len(s) + 1):
        for j in range(i):
            if s[j:i] in dictionary:
                dp[i] = min(dp[i], dp[j])
    return dp[-1]

def answerQueries(n, queries):
    nums = [0] * n
    answer = [0] * len(queries)

    for i, (index, color) in enumerate(queries):
        nums[index] = color

        if index > 0 and nums[index] == nums[index - 1]:
            answer[i] = 1
        if index < n - 1 and nums[index] == nums[index + 1]:
            answer[i] = 1

    return answer

def longest_semi_repetitive_substring(s: str) -> int:
    n = len(s)
    max_len = 0
    start = 0

    for end in range(n):
        if s[end] == s[end - 1]:
            if end - start > 1:
                max_len = max(max_len, end - start)
            start = end

