def min_length(s: str) -> int:
    stack = []
    for char in s:
        if stack and (char == 'B' and stack[-1] == 'A' or char == 'D' and stack[-1] == 'C'):
            stack.pop()
        else:
            stack.append(char)
    return len(stack)

