def minCost(s: str) -> int:
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1
        for j in range(i):
            if s[i] != s[j]:
                dp[i][j] = min(dp[i][j], dp[j][i] + (i - j))

    return min(dp[i][n - 1] for i in range(n))

