def longestEqualSubarray(nums, k):
    max_len = 0
    left = 0
    freq = {}

    for right in range(len(nums)):
        if nums[right] in freq:
            freq[nums[right]] += 1
        else:
            freq[nums[right]] = 1

        while (right - left + 1) - max(freq.values()) > k:
            freq[nums[left]] -= 1
            if freq[nums[left]] == 0:
                del freq[nums[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

def minOperations(num1, num2):
    if num1 == 0:
        return 0
    if num1 < 0:
        return -1

    operations = 0
    while num1 != 0:
        if num1 < num2:
            return -1
        num1 -= num2
        operations += 1

    return operations

