from itertools import permutations

def count_special_permutations(nums):
    MOD = 10**9 + 7
    count = 0
    for perm in permutations(nums):
        is_special = True
        for i in range(len(perm) - 1):
            if perm[i] % perm[i + 1] != 0 and perm[i + 1] % perm[i] != 0:
                is_special = False
                break
        if is_special:
            count += 1
            count %= MOD
    return count

def sum_imbalance_numbers(nums):
    def imbalance_number(subarr):
        sarr = sorted(subarr)
        imbalance = 0
        for i in range(len(sarr) - 1):
            if sarr[i+1] - sarr[i] > 1:
                imbalance += 1
        return imbalance

    total_imbalance = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums) + 1):
            total_imbalance += imbalance_number(nums[i:j])

    return total_imbalance

def countCompleteSubarrays(nums):
    from collections import Counter

    n = len(nums)
    count = Counter(nums)
    total_subarrays = 0

    for num in count:
        if count[num] == n:
            total_subarrays += n * (n + 1) // 2

    return total_subarrays

