def prime_pairs(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = [i for i in range(2, n + 1) if is_prime(i)]
    prime_pairs = []
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            if primes[i] + primes[j] == n:
                prime_pairs.append([primes[i], primes[j]])
    return sorted(prime_pairs, key=lambda x: x[0])

def canMakeAllZero(nums, k):
    n = len(nums)
    for i in range(n):
        if nums[i] != 0:
            for j in range(i, min(i + k, n)):
                if nums[j] > 0:
                    nums[j] -= 1
                    break
    return all(num == 0 for num in nums)

def min_changes_to_semi_palindrome(s, k):
    def min_changes_to_palindrome(s):
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if length % 2 == 0:
                    dp[i][j] = dp[i + 1][j - 1] + (s[i] != s[j])
                else:
                    dp[i][j] = dp[i + 1][j - 1] + (s[i] != s[j]) + min(dp[i + 1][j - 2], dp[i + 2][j - 2])
        return dp[0][n - 1]

    def is_semi_palindrome(s, d):
        n = len(s)
        for i in range(n):
            for j in range(i, n):
                if (j - i) % d == 0:
                    if s[i] != s[j]:
                        return True
        return False

    dp = [[float('inf')] * (k + 1) for _ in range(len(s) + 1)]
    dp[0][0] = 0
    for i in range(1, len(s) + 1):
        for j in range(1, min(i, k) + 1):
            for l in range(i):
                dp[i][j] = min(dp[i][j], dp[l][j - 1] + min_changes_to_palindrome(s[l:i]))

    return dp[len(s)][k]

def countWays(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[j] = (dp[j] + dp[j - i**x]) % MOD

    return dp[n]

def min_partitions(s: str) -> int:
    if not s:
        return -1

    # Initialize the minimum number of partitions to a large number
    min_partitions = float('inf')

    # Iterate over all possible partitions
    for i in range(1, len(s) + 1):
        # Check if the current partition is beautiful
        if all(s[j:i] != '0' for j in range(i)):
            # If it is, update the minimum number of partitions
            min_partitions = min(min_partitions, i)

    # If the minimum number of partitions is still infinity, return -1
    return min_partitions if min_partitions != float('inf') else -1

def longestValidSubstring(word, forbidden):
    forbidden_set = set(forbidden)
    max_length = 0
    for i in range(len(word)):
        for j in range(i, len(word)):
            substring = word[i:j+1]
            if substring not in forbidden_set:
                max_length = max(max_length, j-i+1)
    return max_length

def max_beauty(nums, k):
    nums.sort()
    max_beauty = 1
    left = 0

    for right in range(len(nums)):
        while nums[right] - nums[left] > 2 * k:
            left += 1
        max_beauty = max(max_beauty, right - left + 1)

    return max_beauty

def maxScore(nums, x):
    n = len(nums)
    dp = [0] * n
    dp[0] = nums[0]

    for i in range(1, n):
        dp[i] = dp[i-1] + nums[i]
        if nums[i] % 2 != nums[i-1] % 2:
            dp[i] -= x

    return max(dp)

