def countSteppingNumbers(low: str, high: str) -> int:
    MOD = 10**9 + 7
    low, high = int(low), int(high)
    low_str, high_str = str(low), str(high)
    low_len, high_len = len(low_str), len(high_str)

    dp = [[0] * 10 for _ in range(10)]
    dp[0] = [1] * 10

    for i in range(1, 10):
        dp[i][0] = 1
        dp[i][1] = 1

    for i in range(1, low_len):
        for j in range(1, 10):
            if abs(int(low_str[i]) - j) == 1:
                dp[j][i] = (dp[j][i-1] + dp[j-1][i-1]) % MOD

    for i in range(low_len, high_len):
        for j in range(1, 10):
            if abs(int(high_str[i]) - j) == 1:
                dp[j][i] = (dp[j][i-1] + dp[j-1][i-1]) % MOD

    count = 0
    for j in range(1, 10):
        count = (count + dp[j][low_len-1]) % MOD

    return count

def countPairs(coordinates, k):
    count = 0
    for i in range(len(coordinates)):
        for j in range(i + 1, len(coordinates)):
            if (coordinates[i][0] ^ coordinates[j][0]) + (coordinates[i][1] ^ coordinates[j][1]) == k:
                count += 1
    return count

def maximizeTheProfit(n, offers):
    dp = [0] * (n + 1)
    for start, end, gold in offers:
        for i in range(start, end + 1):
            dp[i] = max(dp[i], dp[start] + gold)
    return dp[n]

def can_make_equal(s1, s2):
    # Check if the strings are already equal
    if s1 == s2:
        return True

    # Check if we can make the strings equal by swapping characters at indices i and i+2
    for i in range(0, 4, 2):
        if s1[i] != s2[i]:
            return False

    return True

def count_beautiful_integers(low, high, k):
    def is_beautiful(num):
        even_count = sum(1 for digit in str(num) if int(digit) % 2 == 0)
        odd_count = len(str(num)) - even_count
        return even_count == odd_count and num % k == 0

    beautiful_count = 0
    for num in range(low, high + 1):
        if is_beautiful(num):
            beautiful_count += 1
    return beautiful_count

def can_make_subsequence(str1, str2):
    str1 = list(str1)
    str2_index = 0

    for char in str2:
        if char in str1:
            str1[str1.index(char)] = chr(ord(char) + 1)
            str2_index += 1
            if str2_index == len(str2):
                return True

    return False

def furthest_point_from_origin(moves: str) -> int:
    max_distance = 0
    current_position = 0

    for move in moves:
        if move == 'L':
            current_position -= 1
        elif move == 'R':
            current_position += 1
        else:  # move == '_'
            current_position += 1

        max_distance = max(max_distance, abs(current_position))

    return max_distance

def countWays(s: str, t: str, k: int) -> int:
    MOD = 10**9 + 7
    n = len(s)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD

    return dp[n][k]

def min_operations(nums, target):
    operations = 0
    while target > 0:
        if target & 1:
            if nums[0] == 1:
                nums.pop(0)
                operations += 1
                target -= 1
            else:
                nums.pop(0)
                operations += 1
                target -= nums[0]
        else:
            nums.pop(0)
            operations += 1
            target -= nums[0]
    return operations if target == 0 else -1

def product_matrix(grid):
    MOD = 12345
    n, m = len(grid), len(grid[0])
    p = [[0]*m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            product = 1
            for k in range(n):
                for l in range(m):
                    if k != i and l != j:
                        product = (product * grid[k][l]) % MOD
            p[i][j] = product

    return p

def maxReceiverSum(receiver, k):
    n = len(receiver)
    visited = [False] * n
    max_sum = 0

    def dfs(node, step):
        nonlocal max_sum
        if visited[node]:
            return
        visited[node] = True
        sum_cycle = node + receiver[node] + receiver[receiver[node]] + ... + receiver[step]
        max_sum = max(max_sum, sum_cycle)
        for next_node in range(n):
            if receiver[next_node] == node:
                dfs(next_node, step + 1)
        visited[node] = False

    for i in range(n):
        if not visited[i]:
            dfs(i, 0)

    return max_sum

def minCost(s1, s2, x):
    n = len(s1)
    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            if s1[j] != s2[i - 1]:
                dp[i][j] = min(dp[i][j], dp[j][i - 1] + x)
            if j + 1 < i:
                dp[i][j] = min(dp[i][j], dp[j + 1][i - 1] + 1)

    return dp[n][n] if dp[n][n] != float('inf') else -1

def count_covered_points(nums):
