import math

def is_perfect_square(x):
    s = int(math.sqrt(x))
    return s * s == x

def max_element_sum(nums):
    n = len(nums)
    max_sum = 0
    for i in range(1, n + 1):
        subset_sum = 0
        for j in range(i, n + 1):
            if is_perfect_square(nums[i - 1] * nums[j - 1]):
                subset_sum += nums[j - 1]
        max_sum = max(max_sum, subset_sum)
    return max_sum

def maximumOddBinaryNumber(s: str) -> str:
    ones = [i for i, c in enumerate(s) if c == '1']
    ones.sort(reverse=True)
    ones.insert(0, ones[0])
    return ''.join(ones)

def maxSubarrays(nums):
    n = len(nums)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        for j in range(i - 1, -1, -1):
            if nums[j] & nums[j + 1] & ... & nums[i - 1] == 0:
                dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]

