def count_covered_people(N, M, parents, insurances):
    covered = set()

    for x, y in insurances:
        queue = [x]
        while queue:
            person = queue.pop(0)
            if person not in covered:
                covered.add(person)
                for child in range(y):
                    queue.append(parents[person][child])

    return len(covered)

