import math

MOD = 998244353

def mod_inverse(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    if x1 < 0:
        x1 += m0
    return x1

def solve(N, A):
    total_ways = 1
    for a in A:
        total_ways = (total_ways * (a + 1)) % MOD

    ways_to_sum_to_10 = 0
    for i in range(N):
        for j in range(N):
            if i != j:
                ways_to_sum_to_10 = (ways_to_sum_to_10 + (A[i] + A[j] - 1) * mod_inverse(A[i] + A[j] - 2, MOD)) % MOD

    probability = (ways_to_sum_to_10 * mod_inverse(total_ways, MOD)) % MOD
    return probability

