def solve_problem(N, R, C):
    # Initialize the grid with empty strings
    grid = [['' for _ in range(N)] for _ in range(N)]

    # Fill the grid based on the given conditions
    for i in range(N):
        grid[i][0] = R[i]
        grid[0][i] = C[i]

    # Fill the rest of the grid
    for i in range(1, N):
        for j in range(1, N):
            if grid[i-1][j-1] == 'A':
                grid[i][j] = 'A'
            elif grid[i-1][j-1] == 'B':
                grid[i][j] = 'B'
            elif grid[i-1][j-1] == 'C':
                grid[i][j] = 'C'

    # Check if the grid satisfies all conditions
    for i in range(N):
        for j in range(N):
            if grid[i][j] != '.':
                if grid[i][j] != R[i]:
                    return "No"
                if grid[i][j] != C[i]:
                    return "No"

    # If the grid satisfies all conditions, print the grid
    for row in grid:
