def find_X_sequence(N, L, R, A):
    X = [L] * N
    for i in range(N):
        for j in range(i, N):
            if abs(X[i] - A[i]) <= abs(X[j] - A[j]):
                X[j] = X[i]
                break
    return X

def count_black_squares(N, Q, P, queries):
    results = []
    for A, B, C, D in queries:
        count = 0
        for i in range(A, C + 1):
            for j in range(B, D + 1):
                if P[i % N][j % N] == 'B':
                    count += 1
        results.append(count)
    return results

