def shortest_substring(arr):
    answer = []
    for s in arr:
        substrings = set()
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                substrings.add(s[i:j])
        shortest = min(substrings, key=lambda x: (len(x), x))
        answer.append(shortest)
    return answer

def maxStrength(nums, k):
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + nums[i - 1] * (j - 1))

    return dp[n][k]

def length_of_longest_substring(s: str) -> int:
    char_count = {}
    left = 0
    max_len = 0

    for right in range(len(s)):
        char = s[right]
        char_count[char] = char_count.get(char, 0) + 1

        while char_count[char] > 2:
            char_count[s[left]] -= 1
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

def min_operations(k):
    nums = [1]
    operations = 0
    while sum(nums) < k:
        if len(nums) == 1:
            nums.append(nums[0] + 1)
        else:
            nums.append(nums[-1] + 1)
        operations += 1
    return operations

def count_alternating_subarrays(nums):
    n = len(nums)
    count = 0
    for i in range(n):
        if nums[i] == 0:
            count += 1
        else:
            count += n - i
    return count

def min_max_distance(points):
    def manhattan_distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    n = len(points)
    min_max_dist = float('inf')

    for i in range(n):
        max_dist = 0
        for j in range(n):
            if i != j:
                max_dist = max(max_dist, manhattan_distance(points[i], points[j]))
        min_max_dist = min(min_max_dist, max_dist)

    return min_max_dist

def distance(s_1, s_2):
