    return min_distance

def make_lexicographically_smallest(s, k):
    s = list(s)
    for i in range(len(s)):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            if distance(s[i], c) <= k:
                s[i] = c
                break
    return ''.join(s)

def minOperations(nums, k):
    nums.sort()
    n = len(nums)
    median = nums[n//2]
    operations = 0

    for i in range(n):
        if nums[i] < median:
            operations += median - nums[i]
        elif nums[i] > median:
            operations += nums[i] - median

    return operations

def min_sum_of_values(nums, andValues):
    n = len(nums)
    m = len(andValues)

    # Initialize DP table
    dp = [[float('inf')] * (1 << (n - m)) for _ in range(m + 1)]
    dp[0][0] = 0

    for i in range(1, m + 1):
        for j in range(1 << (n - m)):
            if j & (1 << (n - m)):
                continue
            for k in range(i):
                if j & (1 << k):
                    continue
                if nums[k] & andValues[i - 1] == andValues[i - 1]:
                    dp[i][j] = min(dp[i][j], dp[k][j ^ (1 << k)] + nums[k])

    return dp[m][(1 << (n - m)) - 1] if dp[m][(1 << (n - m)) - 1] != float('inf') else -1

def sum_of_unmarked_elements(nums, queries):
    n = len(nums)
    marked = [False] * n
    answer = [0] * m

    for i in range(m):
        index, k = queries[i]
        if not marked[index]:
            marked[index] = True

        # Mark k smallest unmarked elements
        for j in range(k):
            if not marked[j]:
                marked[j] = True

        # Calculate the sum of unmarked elements
        unmarked_sum = sum(nums[j] for j in range(n) if not marked[j])
        answer[i] = unmarked_sum

    return answer

def sum_of_power(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums[i - 1]:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - nums[i - 1]]) % MOD

    return sum(dp[n]) % MOD

def shortest_special_subarray(nums, k):
    n = len(nums)
    min_length = float('inf')

    for start in range(n):
        current_or = 0
        for end in range(start, n):
            current_or |= nums[end]
            if current_or >= k:
                min_length = min(min_length, end - start + 1)
                break

    return min_length if min_length != float('inf') else -1

def min_levels_to_gain_more_points(possible):
    n = len(possible)
    alice_points = 0
    bob_points = 0

    for i in range(n):
        if possible[i] == 1:
            alice_points += 1
        else:
            bob_points += 1

        if alice_points > bob_points:
            return i + 1

    return -1

def sum_of_powers(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * n for _ in range(k + 1)]

    for i in range(k):
        dp[i][0] = 0

    for i in range(1, k):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i-1][j-1]) + abs(nums[j] - nums[j-1])

    return sum(dp[k-1]) % MOD

def findMedianOfUniquenessArray(nums):
    n = len(nums)
    uniqueness_array = []

    # Generate the uniqueness array
    for i in range(n):
        distinct_elements = set()
        for j in range(i, n):
            distinct_elements.add(nums[j])
            uniqueness_array.append(len(distinct_elements))

    # Find the median of the uniqueness array
    uniqueness_array.sort()
    mid = len(uniqueness_array) // 2

    if len(uniqueness_array) % 2 == 0:
        return uniqueness_array[mid - 1]
    else:
        return uniqueness_array[mid]

def min_operations_to_k_periodic(word, k):
    n = len(word)
    operations = 0

    for i in range(0, n, k):
        if word[i:i+k] != word[i:i+k][::-1]:
            operations += 1

    return operations

def count_right_triangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                for k in range(len(grid)):
                    if k != i and k != j:
                        if grid[k][j] == 1:
                            count += 1
    return count

def count_stable_arrays(zero, one, limit):
    MOD = 10**9 + 7
    dp = [[0] * (one + 1) for _ in range(zero + 1)]
    dp[0][0] = 1

    for i in range(1, zero + 1):
        for j in range(one + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if j < one:
                dp[i][j] = (dp[i][j] + dp[i - 1][j + 1]) % MOD

    return dp[zero][one]

def maxEnergy(energy, k):
    n = len(energy)
    dp = [0] * n
    dp[0] = energy[0]
    for i in range(1, n):
        dp[i] = max(dp[i-1] + energy[i], dp[i-k] + energy[i])
    return max(dp)

def digit_difference(nums):
    def digit_diff(a, b):
        return sum(1 for x, y in zip(str(a), str(b)) if x != y)

    total_diff = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            total_diff += digit_diff(nums[i], nums[j])

    return total_diff

def countWays(k):
    dp = [0] * (k + 1)
    dp[0] = 1
    jump = 0

    for i in range(1, k + 1):
        if i == 1:
            dp[i] = 2
        else:
            dp[i] = dp[i - 1] + dp[i - 2**jump]
        jump += 1

    return dp[k]

def min_partitions(s: str) -> int:
    count = {}
    for char in s:
        count[char] = count.get(char, 0) + 1

    partitions = 0
    for char in s:
        if count[char] % 2 != 0:
            partitions += 1
            count[char] = 0

    return partitions

def powerful_array(x):
    powers = []
    while x > 0:
        powers.append(1 << (x & -x))
        x >>= 1
    return powers

def big_nums(n):
    powers = []
    i = 1
    while i <= n:
        powers.extend(powerful_array(i))
        i += 1
    return powers

def answer(queries):
    big_nums = big_nums(10**15)
    answer = []
    for from_i, to_i, mod_i in queries:
        product = 1
        for i in range(from_i, to_i + 1):
            product = (product * big_nums[i]) % mod_i
        answer.append(product)
    return answer

def find_occurrences(nums, queries, x):
    answer = []
    for query in queries:
        count = 0
        for num in nums:
            if num == x:
                count += 1
                if count == query:
                    answer.append(nums.index(num))
                    break
        if count < query:
            answer.append(-1)
    return answer
